function docView(f){ if(!f) return '<span class="muted small">No file</span>'; const img=f.dataUrl&&/^image\//.test(f.type)?`<img src="${f.dataUrl}" alt="">`:'📄'; const open=f.dataUrl?` · <a href="${f.dataUrl}" target="_blank" rel="noopener" download="${esc(f.name)}">open</a>`:''; return `<div class="doc">${img}<span>${esc(f.name)} ${f.size?`<span class="muted">(${Math.round(f.size/1024)} KB)</span>`:''}${open}${f.note?`<br><span class="muted">${esc(f.note)}</span>`:''}</span></div>`; }
