/* ---------------- HBV validation engine ---------------- */
function scanKeywords(text){
  const hits=[]; let t=' '+String(text||'').toLowerCase().replace(/[^a-z0-9&é\- ]+/g,' ')+' ';
  // phrases containing flagged words that are HBV-allowed
  t=t.replace(/peanut butter|almond butter|nut butters?|sunflower seed butter|seed butter|buttercream|butter cookies|brown butter|garlic powder|onion powder|lemon juice|lime juice|soup mix(es)?/g,' ');
  t=t.replace(/[a-z]+ (seasonings?|rubs?|spice blends?|spices|mix|mixes|blend|salt)([^a-z])/g,' $2');
  for(const [cat,words] of KW){ for(const w of words){ const re=new RegExp('(^|[^a-z])'+w.replace(/[-]/g,'\\-')+'(s|es)?([^a-z]|$)'); if(re.test(t)){ hits.push({cat,word:w}); break; } } }
  return hits;
}
function validateListing(l, s){
  const issues=[]; const block=(msg,src,cat)=>issues.push({level:'block',msg,src,cat}); const warn=(msg,src)=>issues.push({level:'warn',msg,src});
  const cat=catById(l.categoryId);
  if(!l.categoryId){ block('Choose a food category from the Indiana HBV matrix.','form'); }
  else if(l.categoryId==='other'){ block('This item is not in any HBV-allowed category. Items outside the matrix are treated as potentially TCS (time/temperature control for safety) foods.','matrix: not in allowed_categories','other'); }
  else if(cat && !cat.allowed){ block(`“${cat.category_name}” is a prohibited category under Indiana HBV rules. ${cat.rejection_reason}`,'matrix: prohibited_categories › '+cat.category_id, cat.category_id); }
  if(cat && cat.allowed){
    const r=cat.app_validation_rules||{};
    if(r.requires_filling_attribute_check){
      const f=FILLINGS.find(x=>x.id===l.filling);
      if(!l.filling) block('Select the filling / frosting / topping so we can check it.','app_validation_rules.requires_filling_attribute_check');
      else if((r.restricted_fillings||[]).includes(l.filling)){ const pc=catById('perishable_bakery_fillings'); block(`Restricted filling: “${f?f.t:l.filling}”. ${pc.rejection_reason}`,'app_validation_rules.restricted_fillings','perishable_bakery_fillings'); }
    }
    if(r.prohibit_meat_ingredients && l.containsMeat) block('Dry goods may not contain meat ingredients (including meat powders/bouillon). '+catById('prepared_meals_tcs').rejection_reason,'app_validation_rules.prohibit_meat_ingredients','prepared_meals_tcs');
    if(r.prohibit_liquid_beverages && l.form==='liquid') block('Only dry coffee/tea products are allowed. '+catById('beverages_liquid').rejection_reason,'app_validation_rules.prohibit_liquid_beverages','beverages_liquid');
    if(r.prohibit_low_sugar && l.sugarForm==='low') block('Low-sugar, no-sugar or sugar-free jams/jellies are not allowed. '+catById('canned_acidified_low_acid').rejection_reason,'app_validation_rules.prohibit_low_sugar','canned_acidified_low_acid');
    if(r.requires_ph_or_sugar_declaration && !l.phDecl) block('Declare that this product uses a traditional full-sugar, high-acid formulation (pH / sugar declaration) before publishing.','app_validation_rules.requires_ph_or_sugar_declaration');
    if(l.matchedItem==='__other') warn('Not an exact match to a listed item in this category — an admin may double-check it.','matrix: allowed_items');
  }
  const hits=scanKeywords([l.name,l.desc,l.ingredients].join(' '));
  for(const h of hits){ if(cat && !cat.allowed && h.cat===cat.category_id) continue; const pc=catById(h.cat); block(`The text mentions “${h.word}”, which matches the prohibited category “${pc.category_name}”. ${pc.rejection_reason}`,'keyword scan vs matrix prohibited_items',h.cat); }
  if(!l.ingredients) warn('Ingredients are required on the label (descending order by weight).','IC 16-42-5.3-5');
  if(!l.netWt) warn('Net weight/volume or count is required on the label.','IC 16-42-5.3-5');
  const blocked=issues.some(i=>i.level==='block');
  const k=(s&&s.kitchen)||{};
  let path='HBV', canPublish=!blocked, reason='';
  if(blocked && !l.categoryId){ canPublish=false; reason='Pick a category first.'; }
  else if(blocked){
    if(k.status==='verified'){ path='COMMERCIAL'; canPublish=true; reason='Not allowed under HBV, but allowed because a verified commercial kitchen license is on file.'; }
    else if(k.status==='pending'){ canPublish=false; reason='Not allowed under HBV. Your commercial kitchen license is uploaded but still pending review.'; }
    else { canPublish=false; reason='Not allowed under HBV. Upload a Retail Food Establishment permit or licensed commissary/shared-kitchen proof to sell this item.'; }
  }
  return {issues,blocked,path,canPublish,reason};
}

/* ---------------- router ---------------- */
let after=[]; const then=f=>after.push(f);
const routes=[
  [/^#\/?$/,()=>go('#/browse')],
  [/^#\/browse$/,vBrowse],[/^#\/item\/([\w]+)$/,vItem],[/^#\/cart$/,vCart],[/^#\/checkout$/,vCheckout],[/^#\/order\/([\w,\-]+)$/,vOrderDone],[/^#\/orders$/,vBuyerOrders],
  [/^#\/sell$/,vSellHome],[/^#\/sell\/onboard\/(\d)$/,vOnboard],[/^#\/sell\/listing\/(new|[\w]+)$/,vListingForm],[/^#\/sell\/dashboard$/,vDashboard],
  [/^#\/admin$/,vAdmin],[/^#\/compliance$/,vCompliance]
];
let redirected=false;
function go(h){ redirected=true; if(location.hash===h) setTimeout(render,0); else location.hash=h; return ''; }
function render(){
  const h=location.hash||'#/browse'; const app=$('#app');
  const sellSide=/^#\/(sell|admin)/.test(h);
  $('#role-buy').classList.toggle('active',!sellSide); $('#role-sell').classList.toggle('active',sellSide);
  $('#nav-cart').style.display=sellSide?'none':'';
  $('#cart-count').textContent=db.cart.reduce((a,c)=>a+c.qty,0);
  for(const [re,fn] of routes){ const m=h.match(re); if(m){ after=[]; redirected=false; const out=fn(...m.slice(1)); if(redirected){ after=[]; return; } app.innerHTML=out||''; const fns=after; after=[]; fns.forEach(f=>f()); window.scrollTo(0,0); return; } }
  app.innerHTML='<div class="empty"><h2>Page not found</h2><a class="btn" href="#/browse">Back to browse</a></div>';
}

